import Foundation

/// Literal UI copy in app-local visual compositions. Catalog generated by scripts/cleaner-strings.
func c(_ key: String) -> String { String(localized: String.LocalizationValue(key),bundle: .main) }
func cCount(_ count: Int,key: String) -> String {
    String.localizedStringWithFormat(NSLocalizedString("cleaner.count." + key,bundle: .main,comment: "Cleanup item count, with plural variants"),count)
}
